    },
    {
      "node_code": "N_76bf8016527aff38",
      "definition": "核素治疗是利用放射性核素或其标记化合物释放的射线，对病变组织进行局部或全身照射以达到治疗目的的医学实践，涵盖内照射治疗及靶向核素治疗。",
      "boundary": "本节点特指以治疗为目的的核素应用，如碘-131治疗甲亢或甲状腺癌、镭-223治疗骨转移、Lu-177治疗神经内分泌肿瘤等。与核医学基础的区别在于其侧重临床治疗策略、剂量计算及疗效评估，而非基础物理原理；与肿瘤学的区别在于其特指利用放射性核素的治疗手段，而非手术、化疗或外照射放疗。",
      "includes": [
        "放射性核素内照射治疗（如碘-131、镭-223）",
        "靶向核素治疗（如PRRT）",
        "核素治疗的剂量学计算与疗效评估"
      ],
      "excludes": [
        "外照射放射治疗（如直线加速器放疗）",
        "非核素手段的肿瘤治疗（如手术、化疗）"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_589326bf0b8c3ecd",
          "rule": "本节点侧重核素治疗的临床应用与策略；核医学基础侧重核素治疗的物理与生物学基础原理。"
        },
        {
          "other_code": "N_7ae8db2c6873229e",
          "rule": "本节点特指利用放射性核素的治疗手段；肿瘤学涵盖肿瘤的整体诊疗策略，包括手术、化疗、外照射放疗等。"
        }
      ],
      "cross_boundary_rule": "涉及放射性核素治疗手段时归本节点；涉及外照射放疗或肿瘤综合治疗归肿瘤学；涉及核素治疗基础原理归核医学基础。"
    },
    {
      "node_code": "N_c52586dc1d572a5b",
      "definition": "脏器核医学是应用放射性核素显像技术，对特定器官或系统的功能、代谢及血流进行动态评估与诊断的医学分支，涵盖心、肺、肾、骨、脑等脏器核医学。",
      "boundary": "本节点聚焦于基于器官或系统分类的核医学显像诊断，如心肌灌注显像、肾动态显像、骨显像、脑血流显像等。与PET/SPECT显像的区别在于其按解剖部位或器官系统分类，而非按成像技术分类；与核医学基础的区别在于其侧重临床诊断应用，而非基础原理。",
      "includes": [
        "心血管系统核医学（如心肌灌注显像）",
        "泌尿系统核医学（如肾动态显像）",
        "骨骼系统核医学（如骨显像）"
      ],
      "excludes": [
        "PET或SPECT成像技术的通用原理与设备",
        "核素治疗相关主题"
      ],
      "sibling_distinctions": [
        {
          "other_code": "N_2cc86562226c8155",
          "rule": "本节点按器官系统分类（如心脏、肾脏）；PET显像按成像技术分类，涵盖所有器官的PET应用。"
        },
        {
          "other_code": "N_9effc1e8b3697e70",
          "rule": "本节点按器官系统分类（如心脏、肾脏）；SPECT显像按成像技术分类，涵盖所有器官的SPECT应用。"
        }
      ],
      "cross_boundary_rule": "涉及特定器官的核素显像诊断时归本节点；涉及PET或SPECT技术原理或通用应用时归对应显像节点；涉及核素治疗归核素治疗。"
    }
  ]
}
